'use strict';
const GAME_LANGUAGES=[['pl','Polski'],['en','English'],['es','Español'],['ro','Română'],['de','Deutsch'],['fr','Français'],['it','Italiano'],['pt','Português']];
const LANGUAGE_KEY='zielona-dolina-language';
let gameLanguage='pl';try{const stored=localStorage.getItem(LANGUAGE_KEY);if(GAME_LANGUAGES.some(([id])=>id===stored))gameLanguage=stored}catch{}
const localeMaps=GAME_LANGUAGES.map((_,i)=>new Map(LOCALE_ROWS.map(row=>[row[0].toLocaleLowerCase('pl'),row[i]])));
const localeEscape=s=>s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
const localePattern=new RegExp('(?<![\\p{L}\\p{N}_])(?:'+LOCALE_ROWS.map(r=>r[0]).sort((a,b)=>b.length-a.length).map(localeEscape).join('|')+')(?![\\p{L}\\p{N}_])','giu');
const localeCache=new Map(),localeNodes=new WeakMap(),localeAttributes=new WeakMap();
let localeObserver=null,localeTownPattern=null,localeTownSource=null;
function localeTownNames(){if(typeof state==='undefined'||!state.towns?.length)return null;if(localeTownSource!==state.towns){localeTownSource=state.towns;const names=state.towns.map(t=>t.name).filter(Boolean);localeTownPattern=names.length?new RegExp(names.sort((a,b)=>b.length-a.length).map(localeEscape).join('|'),'g'):null}return localeTownPattern}
function translateGameText(input){const text=String(input??'');if(gameLanguage==='pl'||!text.trim())return text;const cached=localeCache.get(text);if(cached!==undefined)return cached;const column=GAME_LANGUAGES.findIndex(([id])=>id===gameLanguage),map=localeMaps[column];const summary=LOCALE_SUMMARIES.find(row=>text.trim().startsWith(row[0]));if(summary){const output=summary[column];if(localeCache.size>=4096)localeCache.clear();localeCache.set(text,output);return output}const names=[],townPattern=localeTownNames();let source=townPattern?text.replace(townPattern,n=>{names.push(n);return '\uE000'+(names.length-1)+'\uE001'}):text;
 const translated=source.replace(localePattern,match=>{const value=map.get(match.toLocaleLowerCase('pl'));if(value===undefined)return match;if(match.length>2&&match===match.toLocaleUpperCase('pl'))return value.toLocaleUpperCase(gameLanguage);if(value===value.toLocaleUpperCase(gameLanguage)&&match===match.toLocaleLowerCase('pl')){const lower=value.toLocaleLowerCase(gameLanguage);return gameLanguage==='de'?lower[0].toLocaleUpperCase('de')+lower.slice(1):lower}return value}).replace(/\uE000(\d+)\uE001/g,(_,i)=>names[Number(i)]);
 if(localeCache.size>=4096)localeCache.clear();localeCache.set(text,translated);return translated;
}
function localeIgnored(el){return !el||['SCRIPT','STYLE','OPTION','KBD','CODE'].includes(el.tagName)||el.closest?.('[data-no-translate]')}
function translateLocaleNode(node){if(node.nodeType===3){if(localeIgnored(node.parentElement))return;const current=node.nodeValue,old=localeNodes.get(node);if(old&&current===old.output&&old.language===gameLanguage)return;const original=old&&current===old.output?old.original:current,output=translateGameText(original);localeNodes.set(node,{original,output,language:gameLanguage});if(output!==current)node.nodeValue=output;return}if(node.nodeType!==1||localeIgnored(node))return;
 for(const attr of ['title','aria-label','placeholder']){const value=node.getAttribute(attr);if(value===null)continue;let record=localeAttributes.get(node);if(!record){record={};localeAttributes.set(node,record)}const old=record[attr],original=old&&value===old.output?old.original:value,output=translateGameText(original);record[attr]={original,output};if(output!==value)node.setAttribute(attr,output)}
 for(const child of node.childNodes)translateLocaleNode(child);
}
function applyGameLanguage(){if(!document.body)return;document.documentElement.lang=gameLanguage;document.title=translateGameText('Zielona Dolina — załóż swoją osadę');const select=document.getElementById('languageSelect');if(select){select.value=gameLanguage;select.setAttribute('aria-label',translateGameText('Język'));document.getElementById('languageLabel').textContent=translateGameText('Język')}updateLocalizedHelp();translateLocaleNode(document.body)}
function setGameLanguage(language){if(!GAME_LANGUAGES.some(([id])=>id===language))return false;gameLanguage=language;localeCache.clear();try{localStorage.setItem(LANGUAGE_KEY,language)}catch{}if(typeof keys!=='undefined')keys={};applyGameLanguage();return true}
function updateLocalizedHelp(){const article=document.querySelector('#overlay article');if(!article)return;let guide=document.getElementById('localizedHelp');if(!guide){guide=document.createElement('div');guide.id='localizedHelp';guide.setAttribute('data-no-translate','');article.insertBefore(guide,document.getElementById('play'))}for(const paragraph of article.querySelectorAll(':scope > p'))paragraph.hidden=gameLanguage!=='pl';guide.hidden=gameLanguage==='pl';if(gameLanguage!=='pl'){const map=localeMaps[GAME_LANGUAGES.findIndex(([id])=>id===gameLanguage)];guide.replaceChildren(...Array.from({length:8},(_,i)=>{const p=document.createElement('p');p.textContent=map.get('help.'+(i+1))||'';return p}))}}
function initGameLanguages(){const select=document.getElementById('languageSelect');if(!select)return;for(const [id,name] of GAME_LANGUAGES){const option=document.createElement('option');option.value=id;option.textContent=name;select.append(option)}select.value=gameLanguage;select.onchange=()=>setGameLanguage(select.value);applyGameLanguage();localeObserver=new MutationObserver(records=>{const roots=new Set();for(const record of records){if(record.type==='characterData')roots.add(record.target);else if(record.type==='attributes')roots.add(record.target);else for(const node of record.addedNodes)roots.add(node)}for(const node of roots)translateLocaleNode(node)});localeObserver.observe(document.body,{subtree:true,childList:true,characterData:true,attributes:true,attributeFilter:['title','aria-label','placeholder']})}
if(typeof CanvasRenderingContext2D!=='undefined'){const originalFillText=CanvasRenderingContext2D.prototype.fillText;CanvasRenderingContext2D.prototype.fillText=function(text,...args){return originalFillText.call(this,translateGameText(text),...args)};const originalMeasureText=CanvasRenderingContext2D.prototype.measureText;CanvasRenderingContext2D.prototype.measureText=function(text){return originalMeasureText.call(this,translateGameText(text))}}
if(typeof window.confirm==='function'){const originalConfirm=window.confirm.bind(window);window.confirm=message=>originalConfirm(translateGameText(message))}
if(document.readyState==='loading')window.addEventListener('DOMContentLoaded',initGameLanguages,{once:true});else initGameLanguages();
